        self.name = name
print(Client('Мира').name)

class Cart:
    def __init__(self, price, qty):
        self.price = price
        self.qty = qty
    def total(self):
        return self.price * self.qty
print(Cart(40, 3).total())

class Counter:
    def __init__(self):
        self.count = 0
    def add(self):
        self.count += 1
c = Counter()
c.add()
print(c.count)

