class Box:
    def __init__(self, width):
        self.width = width
    @property
    def doubled(self):
        return self.width * 2
print(Box(4).doubled)

class Stock:
    def __init__(self):
        self.count = 0
    def add(self, amount):
        if amount > 0:
            self.count += amount
s = Stock()
s.add(3)
print(s.count)

