class Order:
    def __init__(self, price, qty):
        self.price = price
        self.qty = qty
    def total(self):
        return self.price * self.qty
print(Order(25, 4).total())

def countdown(n):
    if n == 0:
        return 0
    return countdown(n - 1)
print(countdown(3))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n-1)
print(factorial(4))

def sum_to(n):
    if n == 0:
        return 0
    return n + sum_to(n-1)
print(sum_to(3))

